ubject to statutory debt limitation: 298,978\n# Total public debt subject to statutory debt limitation: 302,623\n\n# March 31, 1964 (Page 40):\n# Total interest-bearing securities subject to statutory debt limitation: 305,405\n# Total public debt subject to statutory debt limitation: 309,227\n\n# And the Second Liberty Bond Act securities as of March 31, 1964:\n# From Table 1: 309,227\n\n# Now let's calculate the ratios:\n\nr1 = 287538/290174\nr2 = 287140/290144\nr3 = 292485/295652\nr4 = 298978/302623\nr5 = 305405/309227\n\nprint(f\"Ratio 1 (Feb 29, 1960): {r1}\")\nprint(f\"Ratio 2 (Feb 28, 1961): {r2}\")\nprint(f\"Ratio 3 (Mar 31, 1962): {r3}\")\nprint(f\"Ratio 4 (Mar 31, 1963): {r4}\")\nprint(f\"Ratio 5 (Mar 31, 1964): {r5}\")\n\n# Geometric mean\nimport math\ngm = (r1 * r2 * r3 * r4 * r5) ** (1/5)\nprint(f\"\\nGeometric mean: {gm}\")\n\n# Multiply by Second Liberty Bond Act securities as of March 31, 1964\nresult = gm * 309227\nprint(f\"After multiplication: {result}\")\n\n# For the exchange rate - I'll use the official rate of $2.40 per GBP that was in effect in 1964\n# (After the November 1961 devaluation)\nresult_gbp = result * (1/2.40)\nprint(f\"Result in GBP: {result_gbp}\")\nprint(f\"Rounded: {round(result_gbp)}\")\n\n# Alternative if they use $2.80\nresult_gbp_alt = result * (1/2.80)\nprint(f\"\\nAlternative with 2.80: {result_gbp_alt}\")\nprint(f\"Rounded: {round(result_gbp_alt)}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
